import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader('/prism-mock/home/nodes/orb-decor.png');
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const grainAmount = uniform(0.03);

  if (map) {
    const uvNode = uv();
    const texColor = texture(map, uvNode);

    // simple pseudo-random grain based on uv
    const grain = uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233)).sin().mul(43758.5453).fract();
    const grainSigned = grain.sub(0.5).mul(grainAmount);

    const surfaceColor = vec4(
      texColor.r.add(grainSigned),
      texColor.g.add(grainSigned),
      texColor.b.add(grainSigned),
      texColor.a
    );

    material.colorNode = surfaceColor;
  } else {
    material.colorNode = vec4(0.043, 0.043, 0.063, 1.0);
  }

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return mesh;
}
